insert into subject_questions (subject_id, mechanic_type, prompt, correct_answer, distractors, is_selected, slot_position, notes) values
  ('b885a8ab-996f-5b28-9e88-d9965dd460a5', 'know', 'What was Cleopatra''s title as ruler of Egypt?', 'Pharaoh of Egypt', ARRAY['Empress of Rome', 'Queen of Persia', 'Sultana of Egypt']::text[], true, 3, null),
  ('b885a8ab-996f-5b28-9e88-d9965dd460a5', 'era', 'Which dynasty did Cleopatra belong to?', 'Ptolemaic Dynasty', ARRAY['Achaemenid Dynasty', 'Seleucid Dynasty', 'Hasmonean Dynasty']::text[], true, 4, 'Descended from Ptolemy I, a general of Alexander the Great.'),
  ('b885a8ab-996f-5b28-9e88-d9965dd460a5', 'legacy', 'Cleopatra''s death marked the end of what?', 'Ptolemaic Egypt''s independence (annexed by Rome)', ARRAY['The Roman Republic', 'The Egyptian Old Kingdom', 'The Alexandrian Library']::text[], true, 5, 'Egypt became a Roman province after her death.'),
  ('b885a8ab-996f-5b28-9e88-d9965dd460a5', 'contemporaries', 'Which two Roman leaders did Cleopatra form political and romantic alliances with?', 'Julius Caesar and Mark Antony', ARRAY['Augustus and Pompey', 'Pompey and Mark Antony', 'Julius Caesar and Augustus']::text[], true, 6, null),
  ('6eae1c24-aeb8-54a3-8e02-7ea6d7cd2b6a', 'know', 'What theory is Einstein most famous for developing?', 'The theory of relativity', ARRAY['The theory of evolution', 'Quantum mechanics (as sole originator)', 'Newtonian mechanics']::text[], true, 3, null),
  ('6eae1c24-aeb8-54a3-8e02-7ea6d7cd2b6a', 'know', 'For what discovery did Einstein win the 1921 Nobel Prize in Physics?', 'The photoelectric effect', ARRAY['Special relativity', 'General relativity', 'Brownian motion']::text[], true, 4, 'A common misconception is that he won for relativity.'),
  ('6eae1c24-aeb8-54a3-8e02-7ea6d7cd2b6a', 'era', 'What was Einstein''s job when he published his groundbreaking 1905 papers?', 'Clerk at the Swiss Patent Office', ARRAY['University professor', 'Research scientist at Princeton', 'High school teacher']::text[], true, 5, null),
