  ('044bad2a-384d-50d5-be06-59dd2beed9e6', 'inventions', 'Which of the following was invented (or pioneered) at Tiwanaku?', 'Raised-field farming (suka kollus) for high-altitude agriculture', ARRAY['Chinampas, artificial floating agricultural gardens', 'The quipu, a knotted-cord record-keeping system', 'Chuno, a freeze-dried potato preservation method (developed later by the Inca)']::text[], false, null, null),
  ('044bad2a-384d-50d5-be06-59dd2beed9e6', 'world_firsts', 'Which of the following is a verified world ''first'' associated with Tiwanaku?', 'One of the highest-altitude urban civilizations in world history (nearly 12,600 ft / 3,800 m elevation)', ARRAY['The world''s first known direct democracy', 'The world''s first novel', 'One of the world''s first comprehensive written law codes']::text[], false, null, null),
  ('044bad2a-384d-50d5-be06-59dd2beed9e6', 'nickname', 'What is Tiwanaku sometimes called by archaeologists?', 'Cradle of Andean Civilization', ARRAY['The Eternal City', 'The Rose City', 'New City']::text[], false, null, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'know_landmark', 'What is the name of the volcanic crater quarry where most of Rapa Nui''s moai statues were carved directly out of the rock?', 'Rano Raraku', ARRAY['Ahu Tongariki', 'Orongo', 'Ahu Akivi']::text[], true, 3, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'see_location', 'Which of these is Rapa Nui (Easter Island)?', 'Rapa Nui (Easter Island)', ARRAY['Great Zimbabwe', 'Stonehenge', 'Tiwanaku']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'see_landmark', 'Which of these is Rapa Nui (Easter Island)''s signature landmark?', 'Ahu Tongariki (moai platform)', ARRAY['Rano Raraku', 'Orongo', 'Ahu Akivi']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'flag', 'Which country''s flag flies over Rapa Nui (Easter Island) today?', 'Chile', ARRAY['Bolivia', 'Peru', 'Mexico']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'flag_meaning', 'What does the single white star on this location''s national flag represent?', 'A guide toward progress and honor', ARRAY['Mineral resources', 'A vicuna (fauna), a cinchona tree (flora), and a gold cornucopia (mineral wealth)', 'The Aztec founding legend of Tenochtitlan -- an eagle on a cactus devouring a serpent']::text[], false, null, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'language', 'What language was most commonly spoken on Rapa Nui around 1200 AD?', 'Rapa Nui (Polynesian)', ARRAY['Quechua (Runasimi)', 'Nahuatl (Classical Nahuatl)', 'Shona']::text[], false, null, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'inventions', 'Which of the following was pioneered by the Rapa Nui people?', 'A rope-based technique to ''walk'' multi-ton moai statues upright', ARRAY['The quipu, a knotted-cord record-keeping system', 'Chinampas, artificial floating agricultural gardens', 'Raised-field farming (suka kollus)']::text[], false, null, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'world_firsts', 'Which of the following is a verified world ''first'' associated with Rapa Nui?', 'Its undeciphered Rongorongo script may be one of the only writing systems ever invented completely independently', ARRAY['The world''s first known direct democracy', 'The world''s first novel', 'First unified centralized empire in Chinese history']::text[], false, null, null),
  ('4ca3baaa-65fb-5741-92d8-ffbbabc9c97f', 'nickname', 'What is Rapa Nui''s traditional Polynesian nickname?', 'Te Pito o Te Henua ("The Navel of the World")', ARRAY['The Eternal City', 'The Rose City', 'New City']::text[], false, null, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'know_landmark', 'What is the name of the vast imperial palace complex at the heart of Beijing that served Ming and Qing emperors?', 'The Forbidden City', ARRAY['The Lighthouse of Alexandria (Pharos of Alexandria)', 'Sydney Opera House', 'The Palace of Knossos']::text[], true, 3, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'see_location', 'Which of these is Beijing (Forbidden City)?', 'Beijing (Forbidden City)', ARRAY['Mesa Verde', 'Prague', 'Nazca']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'see_landmark', 'Which of these is Beijing (Forbidden City)''s signature landmark?', 'The Forbidden City', ARRAY['The Lighthouse of Alexandria (Pharos of Alexandria)', 'Sydney Opera House', 'The Palace of Knossos']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'flag', 'Which country''s flag flies over Beijing (Forbidden City) today?', 'China', ARRAY['Iran', 'Peru', 'Czech Republic']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'flag_meaning', 'On the flag of China, what do the four smaller stars surrounding the large star represent?', 'The four social classes of China united under the Communist Party (represented by the large star): the working class, peasantry, urban petite bourgeoisie, and national bourgeoisie.', ARRAY['The five pillars of Islam', 'Islam, agriculture, and the prosperity of the land', 'The Swahili people, native to Tanzania and its majority population']::text[], false, null, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'language', 'What language was most commonly spoken at Beijing (Forbidden City) around 1420 AD?', 'Early Mandarin Chinese (the Ming-dynasty court language)', ARRAY['Greek (Koine Greek), the language of the city''s Greek founders and administration, alongside Egyptian spoken by the native population', 'Minoan (recorded in the still-undeciphered Linear A script)', 'Persian (Farsi, including the local Esfahani dialect)']::text[], false, null, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'inventions', 'Which Chinese innovation was essential to constructing and decorating the Forbidden City''s halls and roofs?', 'Glazed ceramic roof tiles (and traditional wooden bracket/dougong construction)', ARRAY['Wi-Fi (wireless LAN technology)', 'One of the world''s earliest known flushing toilets, alongside a piped water and drainage system', 'The Musaeum (Mouseion) of Alexandria']::text[], false, null, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'world_firsts', 'What UNESCO-recognized superlative does the Forbidden City hold among the world''s palace complexes?', 'It is the largest collection of preserved ancient wooden structures in the world.', ARRAY['It is the only Pacific island nation never formally colonized by a European power.', 'Oldest existing, continually operating degree-granting university in the world', 'The first paper mill in the Islamic world.']::text[], false, null, null),
  ('cb331512-9eba-57c6-8caf-972f87f806ff', 'nickname', 'What is the literal English meaning of the Forbidden City''s Chinese name, Zijincheng?', '''Purple Forbidden City''', ARRAY['"Mound City"', '''La Ciudad Califal'' (''The Caliphal City'')', '''Half of the World'' (Nesf-e Jahan)']::text[], false, null, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'know_landmark', 'What vast Safavid-era public square, lined with a royal mosque, palace, and bazaar, forms the heart of historic Isfahan?', 'Naqsh-e Jahan Square (Imam Square)', ARRAY['The Eiffel Tower', 'University of al-Qarawiyyin (Al Quaraouiyine)', 'The Forbidden City']::text[], true, 3, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'see_location', 'Which of these is Isfahan?', 'Isfahan', ARRAY['Cartagena', 'Knossos', 'Ayutthaya']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'see_landmark', 'Which of these is Isfahan''s signature landmark?', 'Naqsh-e Jahan Square (Imam Square)', ARRAY['The Eiffel Tower', 'University of al-Qarawiyyin (Al Quaraouiyine)', 'The Forbidden City']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'flag', 'Which country''s flag flies over Isfahan today?', 'Iran', ARRAY['Morocco', 'China', 'France']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'flag_meaning', 'What does the emblem in the center of Iran''s flag represent?', 'A stylized rendering of the word ''Allah'' combined with four crescents and a sword, adopted after the 1979 revolution.', ARRAY['Impartiality and sovereignty (added in 1920 to distinguish the flag from Poland''s, and originally also representing Moravia and Slovakia).', 'Liberty, equality, and fraternity - the ideals of the French Revolution (blue and red were also historic colors of Paris, joined with royal white).', 'The wealth of Colombia''s soil and gold, and sovereignty.']::text[], false, null, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'language', 'What language was most commonly spoken at Isfahan around 1598 AD?', 'Persian (Farsi, including the local Esfahani dialect)', ARRAY['Ge''ez, the classical Ethiosemitic language of the Aksumite Kingdom', 'Unknown / undeciphered - recorded only in the still-untranslated Indus script', 'Old Thai (Siamese)']::text[], false, null, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'inventions', 'What architectural innovation, widely used on Isfahan''s Safavid mosques, allowed for taller, more visually striking domes?', 'The double-shell (double-dome) construction technique', ARRAY['Glazed ceramic roof tiles (and traditional wooden bracket/dougong construction)', 'Cinema (motion-picture film projection, by the Lumiere brothers)', 'A pressurized underground aqueduct system - the earliest known in the Americas']::text[], false, null, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'world_firsts', 'What superlative is commonly claimed for Isfahan''s Naqsh-e Jahan Square among the world''s public squares?', 'It is often cited as the second-largest city square in the world, after Tiananmen Square in Beijing.', ARRAY['The site of Europe''s first advanced (Bronze Age) palace civilization, the Minoans.', 'It is the oldest university in Central Europe.', 'Australia (a Kilwa coin was found on the Wessel Islands)']::text[], false, null, null),
  ('0c12e8c8-fbff-5873-82e5-e2b9c721c279', 'nickname', 'What was Isfahan''s famous historical nickname, celebrating its splendor under the Safavids?', '''Half of the World'' (Nesf-e Jahan)', ARRAY['"Green table"', '"The Harbour City"', '"The Venice of the Pacific"']::text[], false, null, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'know_landmark', 'What monumental public square, lined with three ornate 15th-17th century madrasas, is Samarkand''s most iconic landmark?', 'The Registan', ARRAY['The Obelisk of Axum (Aksum stelae)', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Nandauwas']::text[], true, 3, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'see_location', 'Which of these is Samarkand?', 'Samarkand', ARRAY['Sydney', 'Mohenjo-daro', 'Alexandria']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'see_landmark', 'Which of these is Samarkand''s signature landmark?', 'The Registan', ARRAY['The Obelisk of Axum (Aksum stelae)', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Nandauwas']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'flag', 'Which country''s flag flies over Samarkand today?', 'Uzbekistan', ARRAY['United States', 'Colombia', 'France']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'flag_meaning', 'What do the twelve stars on the flag of Uzbekistan represent?', 'The twelve provinces (regions) of Uzbekistan.', ARRAY['Egypt''s national emblem, symbolizing the country''s strength and sovereignty', 'Pakistan''s religious minorities (non-Muslim communities).', 'The 50 U.S. states']::text[], false, null, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'language', 'What language was most commonly spoken at Samarkand around 1370 AD?', 'Persian (Tajik), the dominant language of Timurid administration and culture, alongside Chagatai Turkic', ARRAY['Unknown/undetermined - Cahokia''s Mississippian inhabitants left no written language, so their specific spoken language was never directly recorded', 'Persian (Farsi, including the local Esfahani dialect)', 'Czech, alongside German (widely used among the city''s substantial German-speaking population and Latin-using clergy/scholars)']::text[], false, null, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'inventions', 'What craft technology reached the Islamic world for the first time via a paper mill established at Samarkand in the 8th century?', 'Papermaking (learned from Chinese prisoners after the Battle of Talas, 751 AD)', ARRAY['Reservoirs and check dams (such as the Far View Reservoir)', 'A university (Charles University, the first university in Central Europe)', 'The double-shell (double-dome) construction technique']::text[], false, null, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'world_firsts', 'What was Samarkand''s paper mill, founded around 751 AD, the first of in the Islamic world?', 'The first paper mill in the Islamic world.', ARRAY['One of the world''s first public water tanks / earliest known urban sanitation systems.', 'The largest winter carnival in the world.', 'A place of cultural and archaeological significance (works of humans), rather than natural scenery']::text[], false, null, null),
  ('04d0c856-7089-50b1-9f77-1596b6df518d', 'nickname', 'What epithet is Samarkand often given, reflecting its role as a great Silk Road crossroads city?', '''Crossroads of Cultures'' / ''Rome of the East''', ARRAY['"Lord Novgorod the Great" (Gospodin Velikiy Novgorod)', 'The ''City of Light'' (Ville Lumiere)', 'The ''City of a Hundred Spires''']::text[], false, null, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'know_landmark', 'What is the name of the famous ruined temple in Ayutthaya Historical Park known for a stone Buddha head entwined in tree roots?', 'Wat Mahathat', ARRAY['Castillo San Felipe de Barajas', 'The Pyramids of Meroe (Nubian pyramids)', 'The Forbidden City']::text[], true, 3, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'see_location', 'Which of these is Ayutthaya?', 'Ayutthaya', ARRAY['Samarkand', 'Beijing (Forbidden City)', 'Tongatapu']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'see_landmark', 'Which of these is Ayutthaya''s signature landmark?', 'Wat Mahathat', ARRAY['Castillo San Felipe de Barajas', 'The Pyramids of Meroe (Nubian pyramids)', 'The Forbidden City']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'flag', 'Which country''s flag flies over Ayutthaya today?', 'Thailand', ARRAY['France', 'Russia', 'Peru']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'flag_meaning', 'On the flag of Thailand, what does the central blue stripe represent?', 'The monarchy (part of the national motto ''Nation, Religion, King'').', ARRAY['Pakistan''s religious minorities (non-Muslim communities).', 'A stylized rendering of the word ''Allah'' combined with four crescents and a sword, adopted after the 1979 revolution.', 'The 13 original British colonies that became the first U.S. states']::text[], false, null, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'language', 'What language was most commonly spoken at Ayutthaya around 1351 AD?', 'Old Thai (Siamese)', ARRAY['Persian (Tajik), the dominant language of Timurid administration and culture, alongside Chagatai Turkic', 'Greek (Koine Greek), the language of the city''s Greek founders and administration, alongside Egyptian spoken by the native population', 'Minoan (recorded in the still-undeciphered Linear A script)']::text[], false, null, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'inventions', 'What administrative innovation did the Ayutthaya Kingdom develop to govern its large multi-ethnic trading population?', 'The sakdina system, a hierarchical land-and-labor-based social ranking system', ARRAY['Birch bark documents (berestyanye gramoty)', 'The Hotel de Glace (Ice Hotel)', 'Reservoirs and check dams (such as the Far View Reservoir)']::text[], false, null, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'world_firsts', 'What global superlative is Ayutthaya sometimes credited with around the year 1700?', 'It may have been the largest city in the world by population at that time.', ARRAY['The world''s first surf lifesaving club (the Bondi Surf Bathers'' Life Saving Club, founded 1907).', 'The site of Europe''s first advanced (Bronze Age) palace civilization, the Minoans.', 'The largest winter carnival in the world.']::text[], false, null, null),
  ('5652333e-1d16-5698-bbd2-2180a545cf50', 'nickname', 'What nickname did European traders give the era''s flourishing Ayutthaya, comparing it to a great world power?', 'One of the ''three great powers of Asia'' (alongside Ming China and Vijayanagara)', ARRAY['The Nazca Lines', '"Lord Novgorod the Great" (Gospodin Velikiy Novgorod)', '''Half of the World'' (Nesf-e Jahan)']::text[], false, null, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'know_landmark', 'What is the name of the large, precisely engineered public water tank at the center of Mohenjo-daro?', 'The Great Bath', ARRAY['Monks Mound', 'St. Sophia Cathedral, Novgorod', 'Ha''amonga ''a Maui']::text[], true, 3, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'see_location', 'Which of these is Mohenjo-daro?', 'Mohenjo-daro', ARRAY['Isfahan', 'Palenque', 'Alexandria']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'see_landmark', 'Which of these is Mohenjo-daro''s signature landmark?', 'The Great Bath', ARRAY['Monks Mound', 'St. Sophia Cathedral, Novgorod', 'Ha''amonga ''a Maui']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'flag', 'Which country''s flag flies over Mohenjo-daro today?', 'Pakistan', ARRAY['Uzbekistan', 'Egypt', 'China']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'flag_meaning', 'On the flag of Pakistan, what does the white vertical stripe represent?', 'Pakistan''s religious minorities (non-Muslim communities).', ARRAY['The Aztec founding legend of Tenochtitlan, in which this sign revealed the divinely chosen site for the Aztec capital.', 'Christianity, the faith adopted by the Tongan monarchy and population in the 19th century.', 'The 13 original British colonies that became the first U.S. states']::text[], false, null, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'language', 'What language was most commonly spoken at Mohenjo-daro around 2500 BC?', 'Unknown / undeciphered - recorded only in the still-untranslated Indus script', ARRAY['Persian (Tajik), the dominant language of Timurid administration and culture, alongside Chagatai Turkic', 'The Eora language (also called the Sydney Language), spoken by the Aboriginal Eora people, who vastly outnumbered the roughly 1,000 British colonists who arrived that year', 'Quechua was most widely spoken among the Indigenous mine workforce, while Spanish was the language of colonial administration']::text[], false, null, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'inventions', 'What water-engineering innovation is credited to the Indus Valley Civilization at sites like Mohenjo-daro?', 'The circular brick-lined well', ARRAY['Iron smelting and ironworking', 'Birch bark documents (berestyanye gramoty)', 'A "log cabin"-style megalithic technique, stacking naturally hexagonal basalt columns in alternating layers']::text[], false, null, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'world_firsts', 'What is Mohenjo-daro''s Great Bath widely considered among the world''s earliest examples of?', 'One of the world''s first public water tanks / earliest known urban sanitation systems.', ARRAY['Its port, fortresses, and group of monuments were designated a UNESCO World Heritage Site in 1984.', 'Oldest existing, continually operating degree-granting university in the world', 'It was the second-largest city in Europe (after Constantinople), with a population estimated around 400,000.']::text[], false, null, null),
  ('bf214174-7dc1-5ca4-9eee-218a7bbbf506', 'nickname', 'What does the modern name ''Mohenjo-daro'' literally mean?', '''Mound of the Dead Men''', ARRAY['''Purple Forbidden City''', 'The Solomonic dynasty, claiming descent from King Solomon and the Queen of Sheba (Makeda)', 'The Nazca Lines']::text[], false, null, null),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'know_landmark', 'What towering iron lattice structure, built for the 1889 World''s Fair, is Paris''s most famous landmark?', 'The Eiffel Tower', ARRAY['St. Sophia Cathedral, Novgorod', 'University of al-Qarawiyyin (Al Quaraouiyine)', 'Naqsh-e Jahan Square (Imam Square)']::text[], true, 3, null),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'see_location', 'Which of these is Paris?', 'Paris', ARRAY['Prague', 'Potosi', 'Palenque']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'see_landmark', 'Which of these is Paris''s signature landmark?', 'The Eiffel Tower', ARRAY['St. Sophia Cathedral, Novgorod', 'University of al-Qarawiyyin (Al Quaraouiyine)', 'Naqsh-e Jahan Square (Imam Square)']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'flag', 'Which country''s flag flies over Paris today?', 'France', ARRAY['Colombia', 'Czech Republic', 'Tonga']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'flag_meaning', 'What do the three colors of the French flag traditionally represent?', 'Liberty, equality, and fraternity - the ideals of the French Revolution (blue and red were also historic colors of Paris, joined with royal white).', ARRAY['Canada and national unity - it was deliberately chosen as a race-, language-, and region-neutral emblem.', 'A fusion of the historic colors of the medieval kingdoms of Castile and Aragon.', 'The equality and unity of Ethiopia''s peoples, its rays symbolizing a bright, shared future']::text[], false, null, null),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'language', 'What language was most commonly spoken at Paris around 508 AD?', 'Vulgar Latin (Gallo-Romance), transitioning under growing Frankish influence toward Old French', ARRAY['Greek (Koine Greek), the language of the city''s Greek founders and administration, alongside Egyptian spoken by the native population', 'Persian (Farsi, including the local Esfahani dialect)', 'The Eora language (also called the Sydney Language), spoken by the Aboriginal Eora people, who vastly outnumbered the roughly 1,000 British colonists who arrived that year']::text[], false, null, null),
  ('eb303ed0-4c3b-5977-8fc2-2137c437be43', 'inventions', 'What world-changing invention was first publicly demonstrated to a paying audience in Paris in 1895?', 'Cinema (motion-picture film projection, by the Lumiere brothers)', ARRAY['A university (Charles University, the first university in Central Europe)', 'One of the world''s earliest known flushing toilets, alongside a piped water and drainage system', 'The double-shell (double-dome) construction technique']::text[], false, null, null),
