  ('8af81c77-6340-515f-89f1-0501ea8706fa', 'flag_meaning', 'What do the red and yellow colors of the Spanish flag historically represent?', 'A fusion of the historic colors of the medieval kingdoms of Castile and Aragon.', ARRAY['The four social classes of China united under the Communist Party (represented by the large star): the working class, peasantry, urban petite bourgeoisie, and national bourgeoisie.', 'The twelve provinces (regions) of Uzbekistan.', 'Pakistan''s religious minorities (non-Muslim communities).']::text[], false, null, null),
  ('8af81c77-6340-515f-89f1-0501ea8706fa', 'language', 'What language was most commonly spoken at Cordoba around 929 AD?', 'Arabic (Andalusi Arabic), alongside Mozarabic Romance spoken by the local Christian population', ARRAY['An early/ancestral form of Pohnpeian', 'Early Mandarin Chinese (the Ming-dynasty court language)', 'Not definitively known - the Ancestral Puebloans left no written language; linguists believe their descendants'' languages likely include Tanoan and/or Keresan languages still spoken by Pueblo peoples today']::text[], false, null, null),
  ('8af81c77-6340-515f-89f1-0501ea8706fa', 'inventions', 'What field of learning did 10th-century Cordoba''s scholars and libraries make the city a leading center for, far exceeding the rest of contemporary Europe?', 'Medicine, mathematics, astronomy, and botany', ARRAY['Papermaking (learned from Chinese prisoners after the Battle of Talas, 751 AD)', 'Traditional leather tanning', 'Glazed ceramic roof tiles (and traditional wooden bracket/dougong construction)']::text[], false, null, null),
  ('8af81c77-6340-515f-89f1-0501ea8706fa', 'world_firsts', 'What size superlative did Cordoba hold among European cities in the 10th century?', 'It was the second-largest city in Europe (after Constantinople), with a population estimated around 400,000.', ARRAY['A place of cultural and archaeological significance (works of humans), rather than natural scenery', 'The world''s first surf lifesaving club (the Bondi Surf Bathers'' Life Saving Club, founded 1907).', 'Its port, fortresses, and group of monuments were designated a UNESCO World Heritage Site in 1984.']::text[], false, null, null),
