  ('ee0fcfff-a654-5fc3-8725-e086df9c0786', 'flag_meaning', 'What do the 13 stripes on the United States flag represent?', 'The 13 original British colonies that became the first U.S. states', ARRAY['The five pillars of Islam', 'The monarchy (part of the national motto ''Nation, Religion, King'').', 'Liberty, equality, and fraternity - the ideals of the French Revolution (blue and red were also historic colors of Paris, joined with royal white).']::text[], false, null, null),
  ('ee0fcfff-a654-5fc3-8725-e086df9c0786', 'language', 'What language was most commonly spoken at Cahokia around 1050 AD?', 'Unknown/undetermined - Cahokia''s Mississippian inhabitants left no written language, so their specific spoken language was never directly recorded', ARRAY['Czech, alongside German (widely used among the city''s substantial German-speaking population and Latin-using clergy/scholars)', 'Minoan (recorded in the still-undeciphered Linear A script)', 'Swahili (Kiswahili), a Bantu language enriched with Arabic loanwords through Indian Ocean trade']::text[], false, null, null),
  ('ee0fcfff-a654-5fc3-8725-e086df9c0786', 'inventions', 'What large circle of wooden log posts did Cahokia''s inhabitants build and use to track solstices and equinoxes?', 'Woodhenge (Cahokia''s timber solar calendar)', ARRAY['The Hotel de Glace (Ice Hotel)', 'Medicine, mathematics, astronomy, and botany', 'Traditional leather tanning']::text[], false, null, null),
