  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'know_landmark', 'What is the largest and most famous cliff dwelling at Mesa Verde, built into a sandstone alcove and containing around 150 rooms?', 'Cliff Palace', ARRAY['Wat Mahathat', 'Temple of the Inscriptions', 'Ha''amonga ''a Maui']::text[], true, 3, null),
