  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'flag_meaning', 'What do the 50 stars on the United States flag represent?', 'The 50 U.S. states', ARRAY['The Aztec founding legend of Tenochtitlan, in which this sign revealed the divinely chosen site for the Aztec capital.', 'A stylized rendering of the word ''Allah'' combined with four crescents and a sword, adopted after the 1979 revolution.', 'Impartiality and sovereignty (added in 1920 to distinguish the flag from Poland''s, and originally also representing Moravia and Slovakia).']::text[], false, null, null),
  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'language', 'What language was most commonly spoken at Mesa Verde around 1190 AD?', 'Not definitively known - the Ancestral Puebloans left no written language; linguists believe their descendants'' languages likely include Tanoan and/or Keresan languages still spoken by Pueblo peoples today', ARRAY['Arabic and Amazigh (Berber) were both widely spoken; Arabic was the language of the Idrisid court and administration', 'Quechua was most widely spoken among the Indigenous mine workforce, while Spanish was the language of colonial administration', 'Unknown / undeciphered - recorded only in the still-untranslated Indus script']::text[], false, null, null),
  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'inventions', 'What kind of water-conservation structures did the Ancestral Puebloans of Mesa Verde build to capture rainfall and runoff for their mesa-top crops?', 'Reservoirs and check dams (such as the Far View Reservoir)', ARRAY['Cinema (motion-picture film projection, by the Lumiere brothers)', 'The kalia (double-hulled canoe)', 'The Hotel de Glace (Ice Hotel)']::text[], false, null, null),
  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'world_firsts', 'What was Mesa Verde the first U.S. national park created specifically to protect?', 'A place of cultural and archaeological significance (works of humans), rather than natural scenery', ARRAY['It is the only Pacific island nation never formally colonized by a European power.', 'The world''s first surf lifesaving club (the Bondi Surf Bathers'' Life Saving Club, founded 1907).', 'Australia (a Kilwa coin was found on the Wessel Islands)']::text[], false, null, null),
  ('9d8849eb-81ea-56ea-9403-cbfbcc87d01a', 'nickname', 'What does the Spanish name "Mesa Verde," given by Spanish explorers, literally mean?', '"Green table"', ARRAY['''Purple Forbidden City''', 'The ''City of Light'' (Ville Lumiere)', 'The ''City of a Hundred Spires''']::text[], false, null, null),
