  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'know_landmark', 'What is the name of the famous Nazca geoglyph depicting an animal roughly 93 by 58 meters in size?', 'The Monkey (geoglyph)', ARRAY['The Great Bath', 'The Eiffel Tower', 'Nandauwas']::text[], true, 3, null),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'see_location', 'Which of these is Nazca?', 'Nazca', ARRAY['Tongatapu', 'Quebec City', 'Nan Madol']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
