  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'flag', 'Which country''s flag flies over Nazca today?', 'Peru', ARRAY['France', 'Greece', 'Colombia']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'flag_meaning', 'What does the red on Peru''s national flag traditionally represent?', 'The blood spilled by Peruvian freedom fighters during the struggle for independence (white represents purity and peace).', ARRAY['The Swahili people, native to Tanzania and its majority population', 'Egypt''s national emblem, symbolizing the country''s strength and sovereignty', 'The wealth of Colombia''s soil and gold, and sovereignty.']::text[], false, null, null),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'language', 'What language was most commonly spoken by the people who made the Nazca Lines around 100 BC?', 'Unknown - the Nazca had no writing system, so their spoken language is not preserved in the historical record', ARRAY['Old East Slavic (the local Old Novgorod dialect), alongside Finnic languages spoken by neighboring tribes', 'Czech, alongside German (widely used among the city''s substantial German-speaking population and Latin-using clergy/scholars)', 'French, spoken by Champlain''s colonists (Algonquian and Iroquoian languages were spoken by the Indigenous peoples of the surrounding region)']::text[], false, null, null),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'inventions', 'What underground water technology did the Nazca develop to survive in one of the driest deserts on Earth?', 'Puquios - underground spiral aqueduct/filtration systems that tapped groundwater for irrigation', ARRAY['Cinema (motion-picture film projection, by the Lumiere brothers)', 'Mint its own silver and copper coins', 'Wi-Fi (wireless LAN technology)']::text[], false, null, null),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'world_firsts', 'What makes the Nazca Lines significant on a global scale among ancient geoglyphs?', 'They form one of the largest collections of geoglyphs in the world, spanning roughly 450+ square kilometers.', ARRAY['The veche, a citizens'' assembly that elected leaders and governed the Novgorod Republic', 'A place of cultural and archaeological significance (works of humans), rather than natural scenery', 'It is the only known ancient city built entirely atop a coral reef.']::text[], false, null, null),
  ('4b6941bd-f9be-5bd1-8dc3-e16584c370fb', 'nickname', 'What are the massive ground drawings at Nazca commonly known as?', 'The Nazca Lines', ARRAY['The Labyrinth (home of the Minotaur)', '''Half of the World'' (Nesf-e Jahan)', '"The Venice of the Pacific"']::text[], false, null, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'know_landmark', 'What massive fortress, among the largest built by the Spanish in the Americas, guards Cartagena?', 'Castillo San Felipe de Barajas', ARRAY['The Great Bath', 'Charles Bridge', 'Cerro Rico']::text[], true, 3, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'see_location', 'Which of these is Cartagena?', 'Cartagena', ARRAY['Axum (Aksum)', 'Ayutthaya', 'Sydney']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'see_landmark', 'Which of these is Cartagena''s signature landmark?', 'Castillo San Felipe de Barajas', ARRAY['The Great Bath', 'Charles Bridge', 'Cerro Rico']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'flag', 'Which country''s flag flies over Cartagena today?', 'Colombia', ARRAY['Czech Republic', 'Sudan', 'Federated States of Micronesia']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'flag_meaning', 'What does the yellow band on Colombia''s flag represent?', 'The wealth of Colombia''s soil and gold, and sovereignty.', ARRAY['The monarchy (part of the national motto ''Nation, Religion, King'').', 'A stylized rendering of the word ''Allah'' combined with four crescents and a sword, adopted after the 1979 revolution.', 'The five pillars of Islam']::text[], false, null, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'language', 'What language was most commonly spoken at Cartagena around 1533 AD?', 'Spanish, brought by Pedro de Heredia''s colonists, though Indigenous Caribbean languages were also spoken in the area at the time of founding', ARRAY['Early Mandarin Chinese (the Ming-dynasty court language)', 'Minoan (recorded in the still-undeciphered Linear A script)', 'Unknown - the Nazca had no writing system, so their spoken language is not preserved in the historical record']::text[], false, null, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'inventions', 'What emergency service did Cartagena pioneer in the Americas following a major 1569 fire?', 'The first organized firefighting squad/brigade in the Americas', ARRAY['The mercury amalgamation ("patio") process', 'Traditional leather tanning', 'The Musaeum (Mouseion) of Alexandria']::text[], false, null, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'world_firsts', 'What UNESCO recognition did Cartagena''s colonial defenses receive?', 'Its port, fortresses, and group of monuments were designated a UNESCO World Heritage Site in 1984.', ARRAY['It was the second-largest city in Europe (after Constantinople), with a population estimated around 400,000.', 'It is the only known ancient city built entirely atop a coral reef.', 'They form one of the largest collections of geoglyphs in the world, spanning roughly 450+ square kilometers.']::text[], false, null, null),
  ('3f8416a0-7a8a-5e4f-83d3-9d25eece28ef', 'nickname', 'What is one of Cartagena''s popular nicknames?', '"La Heroica" (The Heroic City)', ARRAY['The Labyrinth (home of the Minotaur)', '"Lord Novgorod the Great" (Gospodin Velikiy Novgorod)', 'The ''City of a Hundred Spires''']::text[], false, null, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'know_landmark', 'What mountain looms over Potosi and gave the city its legendary silver wealth?', 'Cerro Rico ("Rich Mountain")', ARRAY['University of al-Qarawiyyin (Al Quaraouiyine)', 'The Palace of Knossos', 'The Registan']::text[], true, 3, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'see_location', 'Which of these is Potosi?', 'Potosi', ARRAY['Axum (Aksum)', 'Nan Madol', 'Mesa Verde']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'see_landmark', 'Which of these is Potosi''s signature landmark?', 'Cerro Rico', ARRAY['University of al-Qarawiyyin (Al Quaraouiyine)', 'The Palace of Knossos', 'The Registan']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'flag', 'Which country''s flag flies over Potosi today?', 'Bolivia', ARRAY['Morocco', 'Pakistan', 'Iran']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'flag_meaning', 'What does the red stripe on Bolivia''s flag represent?', 'The blood shed by Bolivia''s heroes in the struggle for independence.', ARRAY['Egypt''s national emblem, symbolizing the country''s strength and sovereignty', 'Canada and national unity - it was deliberately chosen as a race-, language-, and region-neutral emblem.', 'Australia''s geographic location in the Southern Hemisphere, where the constellation is prominent in the night sky.']::text[], false, null, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'language', 'What language was most commonly spoken at Potosi around 1545 AD?', 'Quechua was most widely spoken among the Indigenous mine workforce, while Spanish was the language of colonial administration', ARRAY['Old East Slavic (the local Old Novgorod dialect), alongside Finnic languages spoken by neighboring tribes', 'Minoan (recorded in the still-undeciphered Linear A script)', 'Greek (Koine Greek), the language of the city''s Greek founders and administration, alongside Egyptian spoken by the native population']::text[], false, null, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'inventions', 'What mercury-based silver-refining technique was widely used to process Potosi''s vast ore deposits?', 'The mercury amalgamation ("patio") process', ARRAY['Cinema (motion-picture film projection, by the Lumiere brothers)', 'Traditional leather tanning', 'A "log cabin"-style megalithic technique, stacking naturally hexagonal basalt columns in alternating layers']::text[], false, null, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'world_firsts', 'What ranking did Potosi reportedly reach among world cities by the early 1600s?', 'It became one of the largest cities in the world at the time, reputedly second only to London in population.', ARRAY['A place of cultural and archaeological significance (works of humans), rather than natural scenery', 'The Eiffel Tower', 'It is the only Pacific island nation never formally colonized by a European power.']::text[], false, null, null),
  ('b97c137a-8a9e-5b60-92d0-d13bd99163a2', 'nickname', 'What was Potosi''s title under Spanish colonial rule?', '"Villa Imperial de Potosi" (The Imperial City)', ARRAY['"Green table"', 'The Nazca Lines', 'The ''City of a Hundred Spires''']::text[], false, null, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'know_landmark', 'What is the name of Nan Madol''s royal mortuary islet, enclosed by basalt walls up to 7.5 meters high?', 'Nandauwas', ARRAY['The Lighthouse of Alexandria (Pharos of Alexandria)', 'St. Sophia Cathedral, Novgorod', 'Chateau Frontenac']::text[], true, 3, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'see_location', 'Which of these is Nan Madol?', 'Nan Madol', ARRAY['Cordoba', 'Mesa Verde', 'Ayutthaya']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'see_landmark', 'Which of these is Nan Madol''s signature landmark?', 'Nandauwas', ARRAY['The Lighthouse of Alexandria (Pharos of Alexandria)', 'St. Sophia Cathedral, Novgorod', 'Chateau Frontenac']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'flag', 'Which country''s flag flies over Nan Madol today?', 'Federated States of Micronesia', ARRAY['Iran', 'Pakistan', 'Tanzania']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'flag_meaning', 'What do the four white stars on the flag of the Federated States of Micronesia represent?', 'The four states of the federation - Chuuk, Kosrae, Pohnpei, and Yap.', ARRAY['The Aztec founding legend of Tenochtitlan, in which this sign revealed the divinely chosen site for the Aztec capital.', 'The 50 U.S. states', 'The five pillars of Islam']::text[], false, null, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'language', 'What language was most commonly spoken at Nan Madol around 1180 AD?', 'An early/ancestral form of Pohnpeian', ARRAY['Unknown/undetermined - Cahokia''s Mississippian inhabitants left no written language, so their specific spoken language was never directly recorded', 'Swahili (Kiswahili), a Bantu language enriched with Arabic loanwords through Indian Ocean trade', 'Quechua was most widely spoken among the Indigenous mine workforce, while Spanish was the language of colonial administration']::text[], false, null, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'inventions', 'What distinctive building method did Nan Madol''s builders use to stack massive basalt columns without mortar?', 'A "log cabin"-style megalithic technique, stacking naturally hexagonal basalt columns in alternating layers', ARRAY['The first organized firefighting squad/brigade in the Americas', 'The kalia (double-hulled canoe)', 'Papermaking (learned from Chinese prisoners after the Battle of Talas, 751 AD)']::text[], false, null, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'world_firsts', 'What makes Nan Madol architecturally unique among ancient cities?', 'It is the only known ancient city built entirely atop a coral reef.', ARRAY['It is the largest collection of preserved ancient wooden structures in the world.', 'Oldest existing, continually operating degree-granting university in the world', 'They provide one of the most complete dynastic histories of any Classic Maya city, thanks to unusually extensive carved texts.']::text[], false, null, null),
  ('6a2f9f6b-08c5-593a-8cb5-14c64fed57cc', 'nickname', 'What is Nan Madol''s popular modern nickname?', '"The Venice of the Pacific"', ARRAY['"Green table"', '"Villa Imperial de Potosi" (The Imperial City)', 'The ''City of Light'' (Ville Lumiere)']::text[], false, null, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'know_landmark', 'What massive coral-limestone trilithon, built as a royal gateway on Tongatapu, still stands today?', 'Ha''amonga ''a Maui', ARRAY['The Registan', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Sydney Opera House']::text[], true, 3, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'see_location', 'Which of these is Tongatapu?', 'Tongatapu', ARRAY['Sydney', 'Novgorod (Veliky Novgorod)', 'Ayutthaya']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'see_landmark', 'Which of these is Tongatapu''s signature landmark?', 'Ha''amonga ''a Maui', ARRAY['The Registan', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Sydney Opera House']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'flag', 'Which country''s flag flies over Tongatapu today?', 'Tonga', ARRAY['Tanzania', 'Czech Republic', 'Ethiopia']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'flag_meaning', 'What does the red cross on Tonga''s flag represent?', 'Christianity, the faith adopted by the Tongan monarchy and population in the 19th century.', ARRAY['The equality and unity of Ethiopia''s peoples, its rays symbolizing a bright, shared future', 'The monarchy (part of the national motto ''Nation, Religion, King'').', 'The blood shed by Bolivia''s heroes in the struggle for independence.']::text[], false, null, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'language', 'What language was most commonly spoken at Tongatapu around 950 AD?', 'An early form of Tongan, a Polynesian language', ARRAY['Not definitively known - the Ancestral Puebloans left no written language; linguists believe their descendants'' languages likely include Tanoan and/or Keresan languages still spoken by Pueblo peoples today', 'Ge''ez, the classical Ethiosemitic language of the Aksumite Kingdom', 'Czech, alongside German (widely used among the city''s substantial German-speaking population and Latin-using clergy/scholars)']::text[], false, null, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'inventions', 'What large double-hulled voyaging canoe, capable of carrying up to 100 people, enabled the Tu''i Tonga Empire''s long-distance voyages and tribute trade?', 'The kalia (double-hulled canoe)', ARRAY['Medicine, mathematics, astronomy, and botany', 'The Musaeum (Mouseion) of Alexandria', 'The Ge''ez script (Ethiopic alphabet)']::text[], false, null, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'world_firsts', 'What distinction does Tonga hold among Pacific nations regarding colonization?', 'It is the only Pacific island nation never formally colonized by a European power.', ARRAY['The world''s first surf lifesaving club (the Bondi Surf Bathers'' Life Saving Club, founded 1907).', 'The Eiffel Tower', 'The veche, a citizens'' assembly that elected leaders and governed the Novgorod Republic']::text[], false, null, null),
  ('12efced3-255a-5399-85a3-bb6bd2743a90', 'nickname', 'What nickname did early European visitors, including Captain Cook, give Tonga?', '"The Friendly Islands"', ARRAY['"La Vieille Capitale" (The Old Capital)', 'The ''City of a Hundred Spires''', '"Green table"']::text[], false, null, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'know_landmark', 'What is Sydney''s iconic performing-arts landmark, opened in 1973 and shaped like billowing sails?', 'Sydney Opera House', ARRAY['Charles Bridge', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Cliff Palace']::text[], true, 3, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'see_location', 'Which of these is Sydney?', 'Sydney', ARRAY['Novgorod (Veliky Novgorod)', 'Nazca', 'Alexandria']::text[], true, 4, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'see_landmark', 'Which of these is Sydney''s signature landmark?', 'Sydney Opera House', ARRAY['Charles Bridge', 'The Mezquita-Catedral (Great Mosque-Cathedral of Cordoba)', 'Cliff Palace']::text[], true, 5, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'flag', 'Which country''s flag flies over Sydney today?', 'Australia', ARRAY['France', 'Thailand', 'Tonga']::text[], true, 6, 'Name-only; image/flag graphic not yet sourced (per Location Subject Pack Read Me).'),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'flag_meaning', 'What does the Southern Cross constellation on Australia''s flag represent?', 'Australia''s geographic location in the Southern Hemisphere, where the constellation is prominent in the night sky.', ARRAY['Nobility and frankness (candor)', 'Pakistan''s religious minorities (non-Muslim communities).', 'The Aztec founding legend of Tenochtitlan, in which this sign revealed the divinely chosen site for the Aztec capital.']::text[], false, null, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'language', 'What language was most commonly spoken at Sydney around 1788 AD?', 'The Eora language (also called the Sydney Language), spoken by the Aboriginal Eora people, who vastly outnumbered the roughly 1,000 British colonists who arrived that year', ARRAY['Persian (Farsi, including the local Esfahani dialect)', 'Unknown / undeciphered - recorded only in the still-untranslated Indus script', 'Meroitic, the indigenous Kushite language']::text[], false, null, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'inventions', 'What now-ubiquitous wireless networking technology was invented by CSIRO scientists working in Sydney in the 1990s?', 'Wi-Fi (wireless LAN technology)', ARRAY['One of the world''s earliest known flushing toilets, alongside a piped water and drainage system', 'The sakdina system, a hierarchical land-and-labor-based social ranking system', 'Iron smelting and ironworking']::text[], false, null, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'world_firsts', 'What is Sydney''s Bondi Beach claimed to be the birthplace of?', 'The world''s first surf lifesaving club (the Bondi Surf Bathers'' Life Saving Club, founded 1907).', ARRAY['The largest winter carnival in the world.', 'The Meroitic script', 'They provide one of the most complete dynastic histories of any Classic Maya city, thanks to unusually extensive carved texts.']::text[], false, null, null),
  ('4b3b3709-2358-5512-918b-c5a115852707', 'nickname', 'What is Sydney''s popular nickname?', '"The Harbour City"', ARRAY['''Purple Forbidden City''', '''La Ciudad Califal'' (''The Caliphal City'')', '''Crossroads of Cultures'' / ''Rome of the East''']::text[], false, null, null),
  ('383c305c-22db-53a7-82c0-0c68faab9bc2', 'know', 'What ancient Indian empire did Ashoka rule?', 'The Maurya Empire', ARRAY['The Gupta Empire', 'The Mughal Empire', 'The Chola Empire']::text[], true, 3, null),
  ('383c305c-22db-53a7-82c0-0c68faab9bc2', 'know', 'What religion did Ashoka famously embrace after the Kalinga War?', 'Buddhism', ARRAY['Hinduism', 'Jainism', 'Zoroastrianism']::text[], true, 4, null),
  ('383c305c-22db-53a7-82c0-0c68faab9bc2', 'era', 'Ashoka reigned in the 3rd century BCE, around the same time as which Hellenistic king ruled Egypt?', 'Ptolemy II of Egypt', ARRAY['Julius Caesar', 'Alexander the Great', 'Constantine the Great']::text[], true, 5, null),
  ('383c305c-22db-53a7-82c0-0c68faab9bc2', 'legacy', 'A wheel symbol used in Ashoka''s pillar edicts appears at the center of which national flag today?', 'The flag of India', ARRAY['The flag of Nepal', 'The flag of Sri Lanka', 'The flag of Thailand']::text[], true, 6, null),
  ('2ddee0cd-d96e-5e4b-9ba3-53fe590de869', 'know', 'In which city did Akbar build his short-lived capital, famous for its Buland Darwaza gateway?', 'Fatehpur Sikri', ARRAY['Lahore', 'Delhi', 'Lucknow']::text[], true, 3, null),
  ('2ddee0cd-d96e-5e4b-9ba3-53fe590de869', 'know', 'What tax on non-Muslim subjects did Akbar abolish as part of his religious tolerance policy?', 'The jizya tax', ARRAY['The zakat tax', 'The kharaj tax', 'The customs tax']::text[], true, 4, null),
  ('2ddee0cd-d96e-5e4b-9ba3-53fe590de869', 'era', 'Akbar''s long reign overlapped with which English monarch''s rule?', 'Elizabeth I', ARRAY['Henry VIII', 'Queen Victoria', 'James I']::text[], true, 5, null),
  ('2ddee0cd-d96e-5e4b-9ba3-53fe590de869', 'legacy', 'What term is often used to describe Akbar''s approach to governing India''s diverse religious population?', 'Religious tolerance (''sulh-i-kul'', or peace with all)', ARRAY['Forced religious conversion', 'Caste-based segregation', 'Strict Sharia rule']::text[], true, 6, null),
  ('0a2c6706-fb26-58cd-bf66-81a143147fc2', 'know', 'What massive funerary monument did Qin Shi Huang commission to guard his tomb?', 'The Terracotta Army', ARRAY['The Great Sphinx', 'The Colossus of Rhodes', 'The Moai statues']::text[], true, 3, null),
  ('0a2c6706-fb26-58cd-bf66-81a143147fc2', 'know', 'What title, meaning ''emperor,'' did Qin Shi Huang coin for himself in 221 BC?', 'Huangdi', ARRAY['Tianzi', 'Khagan', 'Pharaoh']::text[], true, 4, null),
  ('0a2c6706-fb26-58cd-bf66-81a143147fc2', 'era', 'Which ancient Mediterranean power was expanding at roughly the same time Qin Shi Huang unified China?', 'The Roman Republic', ARRAY['The Byzantine Empire', 'The Ottoman Empire', 'The Holy Roman Empire']::text[], true, 5, null),
  ('0a2c6706-fb26-58cd-bf66-81a143147fc2', 'legacy', 'Which famous structure traces its earliest origins to defensive walls Qin Shi Huang ordered connected along the northern frontier?', 'The Great Wall of China', ARRAY['The walls of Great Zimbabwe', 'Hadrian''s Wall', 'The Berlin Wall']::text[], true, 6, null),
  ('75ddb42f-6cb7-5591-999d-f87e03f9a61d', 'know', 'What dynasty did Kublai Khan found after completing the conquest of China?', 'The Yuan dynasty', ARRAY['The Ming dynasty', 'The Tang dynasty', 'The Qing dynasty']::text[], true, 3, null),
  ('75ddb42f-6cb7-5591-999d-f87e03f9a61d', 'know', 'What new form of money did Kublai Khan pioneer across his empire?', 'Paper currency (jiaochao)', ARRAY['Gold-backed coinage', 'Silver ingots as the sole legal tender', 'Cowrie-shell money']::text[], true, 4, null),
  ('75ddb42f-6cb7-5591-999d-f87e03f9a61d', 'era', 'Which Venetian explorer served at Kublai Khan''s court and later wrote a famous account of his travels?', 'Marco Polo', ARRAY['Christopher Columbus', 'Vasco da Gama', 'Ferdinand Magellan']::text[], true, 5, null),
  ('75ddb42f-6cb7-5591-999d-f87e03f9a61d', 'legacy', 'Kublai Khan''s capital, Khanbaliq, became the historic core of which modern world capital?', 'Beijing', ARRAY['Ulaanbaatar', 'Seoul', 'Xi''an']::text[], true, 6, null),
  ('47588358-7b9c-572a-a20a-7dd4fc978c5a', 'know', 'What Muslim dynasty did Saladin found?', 'The Ayyubid dynasty', ARRAY['The Fatimid dynasty', 'The Abbasid dynasty', 'The Seljuk dynasty']::text[], true, 3, null),
  ('47588358-7b9c-572a-a20a-7dd4fc978c5a', 'know', 'At which decisive 1187 battle did Saladin destroy the main Crusader army just before retaking Jerusalem?', 'The Battle of Hattin', ARRAY['The Battle of Antioch', 'The Siege of Acre', 'The Battle of Ascalon']::text[], true, 4, null),
  ('47588358-7b9c-572a-a20a-7dd4fc978c5a', 'era', 'Saladin''s recapture of Jerusalem triggered which major European military campaign, in which Richard the Lionheart fought?', 'The Third Crusade', ARRAY['The First Crusade', 'The Second Crusade', 'The Fourth Crusade']::text[], true, 5, null),
  ('47588358-7b9c-572a-a20a-7dd4fc978c5a', 'legacy', 'Saladin is remembered in both Muslim and European traditions chiefly for what quality toward his defeated enemies?', 'Chivalry and mercy toward the defeated', ARRAY['Ruthless mass execution of all captives', 'Forced conversion of all conquered peoples', 'Refusal to ever negotiate with enemies']::text[], true, 6, null),
  ('ee5c8002-e5f3-59a9-bdf7-0538c3ca6365', 'know', 'What short-lived dynasty did Wu Zetian found when she declared herself emperor?', 'The Zhou dynasty (Wu Zhou)', ARRAY['The Song dynasty', 'The Sui dynasty', 'The Later Han dynasty']::text[], true, 3, null),
  ('ee5c8002-e5f3-59a9-bdf7-0538c3ca6365', 'know', 'What title, previously used only by male rulers, did Wu Zetian take as sovereign of China?', 'Huangdi (Emperor)', ARRAY['Empress Dowager', 'Shogun', 'Khan']::text[], true, 4, null),
  ('ee5c8002-e5f3-59a9-bdf7-0538c3ca6365', 'era', 'Wu Zetian rose to power during and ultimately interrupted which long-running Chinese imperial dynasty?', 'The Tang dynasty', ARRAY['The Ming dynasty', 'The Qing dynasty', 'The Han dynasty']::text[], true, 5, null),
  ('ee5c8002-e5f3-59a9-bdf7-0538c3ca6365', 'legacy', 'What reform to China''s civil service did Wu Zetian expand to promote officials based on merit?', 'The imperial examination system', ARRAY['Hereditary noble appointments', 'Military conscription lottery', 'Regional governor auctions']::text[], true, 6, null),
  ('8521b628-3b01-5128-aed2-6320c74d2e5a', 'know', 'In what city did Ho Chi Minh publicly declare Vietnam''s independence in 1945?', 'Hanoi', ARRAY['Saigon', 'Hue', 'Da Nang']::text[], true, 3, null),
  ('8521b628-3b01-5128-aed2-6320c74d2e5a', 'know', 'What political party did Ho Chi Minh found in 1930 that later led Vietnam''s independence movement?', 'The Indochinese Communist Party', ARRAY['The Vietnamese Nationalist Party', 'The Democratic Republic Party', 'The Viet Minh Alliance Party']::text[], true, 4, null),
  ('8521b628-3b01-5128-aed2-6320c74d2e5a', 'era', 'Ho Chi Minh led Vietnam''s independence struggle first against which colonial power?', 'France', ARRAY['Britain', 'Portugal', 'The Netherlands']::text[], true, 5, null),
  ('8521b628-3b01-5128-aed2-6320c74d2e5a', 'legacy', 'What is Vietnam''s largest city, formerly known as Saigon, renamed in Ho Chi Minh''s honor after reunification in 1975?', 'Ho Chi Minh City', ARRAY['Hanoi', 'Hue', 'Can Tho']::text[], true, 6, null),
  ('edf04841-9510-5767-98f8-260ba7370319', 'know', 'To what city was Japan''s imperial capital effectively moved during Emperor Meiji''s reign, renamed from Edo?', 'Tokyo', ARRAY['Osaka', 'Kyoto', 'Yokohama']::text[], true, 3, null),
  ('edf04841-9510-5767-98f8-260ba7370319', 'know', 'Which two wars did Japan win during Emperor Meiji''s reign, cementing its status as a modern world power?', 'The First Sino-Japanese War and the Russo-Japanese War', ARRAY['The Opium Wars and the Boxer Rebellion', 'World War I and World War II', 'The Boshin War and the Satsuma Rebellion']::text[], true, 4, null),
  ('edf04841-9510-5767-98f8-260ba7370319', 'era', 'Which U.S. president mediated the treaty ending the Russo-Japanese War during Emperor Meiji''s reign?', 'Theodore Roosevelt', ARRAY['Abraham Lincoln', 'George Washington', 'Franklin D. Roosevelt']::text[], true, 5, null),
  ('edf04841-9510-5767-98f8-260ba7370319', 'legacy', 'What system of government did Emperor Meiji''s reign establish, including Japan''s first national parliament?', 'A constitutional monarchy with the Imperial Diet', ARRAY['A fully democratic republic', 'A military dictatorship with no legislature', 'A return to pure feudal shogunate rule']::text[], true, 6, null),
  ('40e4aea0-2968-56b5-b383-1572c9d23324', 'know', 'What title did Mansa Musa hold as ruler of the Mali Empire?', 'Mansa of Mali', ARRAY['Pharaoh of Egypt', 'Sultan of Morocco', 'Caliph of Baghdad']::text[], true, 3, null),
  ('40e4aea0-2968-56b5-b383-1572c9d23324', 'know', 'Which city did Mansa Musa develop into a renowned center of Islamic learning?', 'Timbuktu', ARRAY['Cairo', 'Fez', 'Mecca']::text[], true, 4, null),
  ('40e4aea0-2968-56b5-b383-1572c9d23324', 'era', 'In which century did Mansa Musa rule the Mali Empire?', '14th century', ARRAY['10th century', '16th century', '18th century']::text[], true, 5, null),
  ('40e4aea0-2968-56b5-b383-1572c9d23324', 'legacy', 'Mansa Musa is often cited by historians as reputedly...', 'the richest person in history', ARRAY['the first Muslim ruler in Africa', 'the founder of Cairo', 'the last pharaoh of Egypt']::text[], true, 6, null),
  ('d04a5d19-6170-5d80-b54a-388e9876cc88', 'know', 'What weapon did Shaka introduce that revolutionized Zulu warfare?', 'The iklwa (short stabbing spear)', ARRAY['The longbow', 'The war axe', 'The throwing net']::text[], true, 3, null),
  ('d04a5d19-6170-5d80-b54a-388e9876cc88', 'know', 'What military formation is Shaka credited with perfecting?', 'The ''bull horns'' encirclement formation', ARRAY['The phalanx', 'The testudo (tortoise) formation', 'The shield wall']::text[], true, 4, null),
  ('d04a5d19-6170-5d80-b54a-388e9876cc88', 'era', 'Shaka''s rise triggered a period of widespread warfare and displacement in southern Africa known as the...', 'Mfecane', ARRAY['Great Trek', 'Scramble for Africa', 'Bantu Migration']::text[], true, 5, null),
  ('d04a5d19-6170-5d80-b54a-388e9876cc88', 'legacy', 'Which people did Shaka unite into a powerful centralized kingdom?', 'The Zulu people', ARRAY['The Xhosa people', 'The Basotho people', 'The Ashanti people']::text[], true, 6, null),
  ('b372f55f-71c4-5ab1-8343-6b265a8f5a07', 'know', 'Sundiata Keita is celebrated as the founder of which West African empire?', 'The Mali Empire', ARRAY['The Songhai Empire', 'The Ghana Empire', 'The Kanem-Bornu Empire']::text[], true, 3, null),
  ('b372f55f-71c4-5ab1-8343-6b265a8f5a07', 'know', 'At which battle did Sundiata defeat the sorcerer-king Soumaoro Kanté?', 'Battle of Kirina', ARRAY['Battle of Tondibi', 'Battle of Adwa', 'Battle of Dara']::text[], true, 4, null),
  ('b372f55f-71c4-5ab1-8343-6b265a8f5a07', 'era', 'Sundiata''s story has been preserved for centuries primarily through which West African oral tradition?', 'The Epic of Sundiata, recited by griots', ARRAY['Written court chronicles only', 'Ancient Egyptian hieroglyphic records', 'European missionary journals']::text[], true, 5, null),
  ('b372f55f-71c4-5ab1-8343-6b265a8f5a07', 'legacy', 'What title, roughly meaning ''king of kings,'' did Sundiata become the first to hold in Mali?', 'Mansa', ARRAY['Pharaoh', 'Sultan', 'Negus']::text[], true, 6, null),
  ('18f4826b-cc7b-5efe-8e27-e6b8ddc7b977', 'know', 'Over which two kingdoms did Nzinga eventually rule?', 'Ndongo and Matamba', ARRAY['Kongo and Loango', 'Benin and Oyo', 'Asante and Dahomey']::text[], true, 3, null),
  ('18f4826b-cc7b-5efe-8e27-e6b8ddc7b977', 'know', 'What famous gesture of defiance is Nzinga remembered for during her 1622 negotiations with the Portuguese governor?', 'Sitting on a kneeling servant''s back as a throne', ARRAY['Refusing to speak through an interpreter', 'Presenting gifts of gold', 'Signing the treaty in blood']::text[], true, 4, null),
  ('18f4826b-cc7b-5efe-8e27-e6b8ddc7b977', 'era', 'Nzinga''s decades-long struggle was primarily against which European colonial power?', 'Portugal', ARRAY['Spain', 'The Netherlands', 'Britain']::text[], true, 5, null),
  ('18f4826b-cc7b-5efe-8e27-e6b8ddc7b977', 'legacy', 'Nzinga is remembered today as a symbol of resistance against...', 'colonization and the slave trade', ARRAY['religious persecution only', 'Zulu expansion', 'Ottoman rule']::text[], true, 6, null),
  ('96c6b740-badd-5a33-8fd1-eef097ef6c6f', 'know', 'What title did Haile Selassie hold as ruler of Ethiopia?', 'Emperor of Ethiopia', ARRAY['Pharaoh of Ethiopia', 'Sultan of Abyssinia', 'King of Kush']::text[], true, 3, null),
  ('96c6b740-badd-5a33-8fd1-eef097ef6c6f', 'know', 'Haile Selassie famously appealed to which international body after Italy''s 1935 invasion of Ethiopia?', 'The League of Nations', ARRAY['The United Nations', 'The African Union', 'NATO']::text[], true, 4, null),
  ('96c6b740-badd-5a33-8fd1-eef097ef6c6f', 'era', 'Haile Selassie''s reign included Ethiopia''s resistance to invasion and occupation by which European country?', 'Italy', ARRAY['France', 'Britain', 'Germany']::text[], true, 5, null),
  ('96c6b740-badd-5a33-8fd1-eef097ef6c6f', 'legacy', 'Haile Selassie became a revered figure in which religious movement centered in Jamaica?', 'Rastafari', ARRAY['Vodou', 'Santería', 'Candomblé']::text[], true, 6, null),
  ('a3239383-0b1c-560d-9b1c-5f1efb29b15f', 'know', 'What was Ibn Battuta''s profession by training before he became a traveler?', 'Islamic legal scholar (qadi/judge)', ARRAY['Physician', 'Cartographer', 'Merchant sea captain']::text[], true, 3, null),
  ('a3239383-0b1c-560d-9b1c-5f1efb29b15f', 'know', 'What is the title of the travelogue documenting Ibn Battuta''s journeys?', 'The Rihla', ARRAY['The Kitab', 'The Muqaddimah', 'The Shahnameh']::text[], true, 4, null),
  ('a3239383-0b1c-560d-9b1c-5f1efb29b15f', 'era', 'Roughly how many years did Ibn Battuta spend traveling across and beyond the Islamic world?', 'About 30 years', ARRAY['About 5 years', 'About 10 years', 'About 50 years']::text[], true, 5, null),
  ('a3239383-0b1c-560d-9b1c-5f1efb29b15f', 'legacy', 'Ibn Battuta is often compared to which contemporary European traveler for the extent of his journeys?', 'Marco Polo', ARRAY['Christopher Columbus', 'Vasco da Gama', 'Ferdinand Magellan']::text[], true, 6, null),
  ('f1fac717-de06-5025-964d-96f1aea62288', 'know', 'What title did Hatshepsut controversially claim for herself as ruler of Egypt?', 'Pharaoh', ARRAY['Vizier', 'High Priestess', 'Regent-Queen only']::text[], true, 3, null),
  ('f1fac717-de06-5025-964d-96f1aea62288', 'know', 'To which distant land did Hatshepsut send a famous trade expedition?', 'The Land of Punt', ARRAY['The Kingdom of Kush', 'Mesopotamia', 'The Hittite Empire']::text[], true, 4, null),
  ('f1fac717-de06-5025-964d-96f1aea62288', 'era', 'Hatshepsut ruled during which period of ancient Egyptian history?', 'The New Kingdom', ARRAY['The Old Kingdom', 'The Middle Kingdom', 'The Ptolemaic Period']::text[], true, 5, null),
  ('f1fac717-de06-5025-964d-96f1aea62288', 'legacy', 'After her death, Hatshepsut''s monuments and images were largely...', 'defaced and erased by her successors', ARRAY['left untouched for centuries', 'destroyed by foreign invaders only', 'converted into churches']::text[], true, 6, null),
  ('57c6725f-0c17-59c2-9ab5-965e85b83439', 'know', 'What was Atahualpa''s title as ruler of the Inca Empire?', 'Sapa Inca', ARRAY['Pharaoh of the Andes', 'Huey Tlatoani', 'Zipa of Muisca']::text[], true, 3, null),
  ('57c6725f-0c17-59c2-9ab5-965e85b83439', 'know', 'In what Peruvian city was Atahualpa captured by Francisco Pizarro''s forces?', 'Cajamarca', ARRAY['Cusco', 'Quito', 'Lima']::text[], true, 4, null),
  ('57c6725f-0c17-59c2-9ab5-965e85b83439', 'era', 'Atahualpa''s capture and execution occurred during which broader historical process?', 'The Spanish conquest of the Americas', ARRAY['The Reconquista of Spain', 'The Napoleonic Wars', 'The Thirty Years'' War']::text[], true, 5, null),
  ('57c6725f-0c17-59c2-9ab5-965e85b83439', 'legacy', 'What lasting historical distinction does Atahualpa hold?', 'He was the last sovereign emperor of the Inca Empire', ARRAY['He was the first Inca to build Machu Picchu', 'He was the founder of the Inca Empire', 'He was the first Inca to willingly convert to Christianity before the conquest began']::text[], true, 6, null),
  ('ae2aee63-41a3-5dc5-972e-09a4db0796b1', 'know', 'What Inca site is widely believed to have been built as a royal estate for Pachacuti?', 'Machu Picchu', ARRAY['Sacsayhuamán', 'Ollantaytambo', 'Chan Chan']::text[], true, 3, null),
  ('ae2aee63-41a3-5dc5-972e-09a4db0796b1', 'know', 'The name "Pachacuti" is generally translated to mean what?', '"He who transforms the earth" / "earth-shaker"', ARRAY['"Son of the Sun"', '"Keeper of the Sacred Valley"', '"First among equals"']::text[], true, 4, null),
  ('ae2aee63-41a3-5dc5-972e-09a4db0796b1', 'era', 'Pachacuti''s transformation of Cusco and rapid imperial expansion took place in which century?', 'The 15th century', ARRAY['The 12th century', 'The 17th century', 'The 10th century']::text[], true, 5, null),
  ('ae2aee63-41a3-5dc5-972e-09a4db0796b1', 'legacy', 'What is Pachacuti best remembered for founding?', 'The Inca Empire as a major imperial power (Tawantinsuyu)', ARRAY['The Aztec Triple Alliance', 'The city of Tenochtitlan', 'The Nazca Lines']::text[], true, 6, null),
  ('799beae9-132b-56b5-8f28-5b8cb979a14f', 'know', 'What was Tupac Amaru II''s birth name?', 'José Gabriel Condorcanqui', ARRAY['Diego de Almagro', 'Manco Inca Yupanqui', 'Francisco de Toledo']::text[], true, 3, null),
  ('799beae9-132b-56b5-8f28-5b8cb979a14f', 'know', 'What indigenous leadership role did Tupac Amaru II hold before leading his rebellion?', 'Kuraka (regional indigenous chief)', ARRAY['Viceroy', 'Corregidor', 'Bishop']::text[], true, 4, null),
  ('799beae9-132b-56b5-8f28-5b8cb979a14f', 'era', 'Tupac Amaru II''s rebellion against Spanish colonial rule took place in which decade?', 'The 1780s', ARRAY['The 1690s', 'The 1820s', 'The 1750s']::text[], true, 5, null),
  ('799beae9-132b-56b5-8f28-5b8cb979a14f', 'legacy', 'How is Tupac Amaru II remembered in Andean history?', 'As a symbol of indigenous resistance to Spanish colonial rule', ARRAY['As the founder of the Inca Empire', 'As the first President of Peru', 'As a Spanish viceroy who reformed tribute laws']::text[], true, 6, null),
  ('3a9d71b3-6db1-5979-9c80-b8edc29fdcf8', 'know', 'What famous military feat did José de San Martín accomplish in 1817?', 'Leading an army across the Andes Mountains to liberate Chile', ARRAY['Sailing a fleet around Cape Horn', 'Marching an army through the Amazon rainforest', 'Crossing the Panama isthmus by land']::text[], true, 3, null),
  ('3a9d71b3-6db1-5979-9c80-b8edc29fdcf8', 'know', 'What title did San Martín adopt after declaring Peru''s independence?', 'Protector of Peru', ARRAY['Emperor of Peru', 'Viceroy of Peru', 'President of the Andes']::text[], true, 4, null),
  ('3a9d71b3-6db1-5979-9c80-b8edc29fdcf8', 'era', 'San Martín''s military campaigns were part of what broader historical wave?', 'The Spanish American wars of independence', ARRAY['The Napoleonic Wars in Europe', 'The American Revolutionary War', 'The Mexican Revolution']::text[], true, 5, null),
  ('3a9d71b3-6db1-5979-9c80-b8edc29fdcf8', 'legacy', 'What is José de San Martín commonly called across Argentina, Chile, and Peru?', 'El Libertador (The Liberator)', ARRAY['El Caudillo', 'El Conquistador', 'El Emperador']::text[], true, 6, null),
  ('a7e54d1e-0c81-53b0-b0d3-0ccde462ee40', 'know', 'At what age did Pedro II formally become Emperor of Brazil, following his father''s abdication?', 'Five years old', ARRAY['Eighteen years old', 'Twelve years old', 'Twenty-one years old']::text[], true, 3, null),
  ('a7e54d1e-0c81-53b0-b0d3-0ccde462ee40', 'know', 'What law, signed in 1888 during his reign, abolished slavery in Brazil?', 'The Lei Áurea (Golden Law)', ARRAY['The Rio Branco Law', 'The Free Womb Law', 'The Sexagenarian Law']::text[], true, 4, null),
  ('a7e54d1e-0c81-53b0-b0d3-0ccde462ee40', 'era', 'Pedro II''s deposition in 1889 led to the establishment of what form of government in Brazil?', 'A republic', ARRAY['A constitutional monarchy under his daughter', 'A military protectorate of Portugal', 'A federation with Argentina']::text[], true, 5, null),
  ('a7e54d1e-0c81-53b0-b0d3-0ccde462ee40', 'legacy', 'What is Pedro II often remembered as, given his patronage of science, education, and the arts?', 'A scholarly, enlightened monarch', ARRAY['A ruthless military dictator', 'A reclusive hermit-king', 'A puppet ruler controlled by Portugal']::text[], true, 6, null),
  ('dad230da-2ffa-5063-9f65-ca5f87ab0ddd', 'know', 'What title did Bernardo O''Higgins hold as head of state of Chile from 1817 to 1823?', 'Supreme Director', ARRAY['President', 'Viceroy', 'Prime Minister']::text[], true, 3, null),
  ('dad230da-2ffa-5063-9f65-ca5f87ab0ddd', 'know', 'Alongside José de San Martín, O''Higgins won which decisive 1817 battle that opened the road to Santiago?', 'The Battle of Chacabuco', ARRAY['The Battle of Ayacucho', 'The Battle of Boyacá', 'The Battle of Carabobo']::text[], true, 4, null),
  ('dad230da-2ffa-5063-9f65-ca5f87ab0ddd', 'era', 'O''Higgins helped lead Chile''s independence movement during which broader conflict?', 'The Chilean War of Independence', ARRAY['The Mexican War of Independence', 'The Paraguayan War', 'The War of the Pacific']::text[], true, 5, null),
  ('dad230da-2ffa-5063-9f65-ca5f87ab0ddd', 'legacy', 'What is Bernardo O''Higgins regarded as in Chile today?', 'A founding father and national hero of Chilean independence', ARRAY['A colonial-era Spanish governor', 'A 20th-century president', 'A rebel defeated by royalist forces']::text[], true, 6, null),
  ('43fc08ad-9b6c-5c5a-aca0-3620c4612519', 'know', 'What is Kamehameha I best known for achieving around 1810?', 'Unifying the Hawaiian Islands under one rule', ARRAY['Discovering the Hawaiian Islands for Europe', 'Converting Hawaii to Christianity', 'Founding the city of Honolulu']::text[], true, 3, null),
  ('43fc08ad-9b6c-5c5a-aca0-3620c4612519', 'know', 'What decisive 1795 battle helped Kamehameha I conquer Oahu?', 'The Battle of Nu''uanu', ARRAY['The Battle of Moku''ōhai', 'The Battle of Kepaniwai', 'The Battle of Waimea']::text[], true, 4, null),
  ('43fc08ad-9b6c-5c5a-aca0-3620c4612519', 'era', 'Kamehameha I''s unification of Hawaii occurred against the backdrop of what?', 'Increasing contact with European and American traders and explorers', ARRAY['The California Gold Rush', 'World War I in the Pacific', 'The U.S. annexation of Hawaii']::text[], true, 5, null),
  ('43fc08ad-9b6c-5c5a-aca0-3620c4612519', 'legacy', 'What lasting title is Kamehameha I commonly given?', 'Kamehameha the Great', ARRAY['Kamehameha the Conqueror-King', 'Kamehameha the Wise', 'Kamehameha the Navigator']::text[], true, 6, null),
  ('0e2b6abc-5ca1-542e-99af-93af79a30ab3', 'know', 'What is Queen Liliuokalani best known for in Hawaiian history?', 'Being the last reigning monarch of the Kingdom of Hawaii', ARRAY['Being the first Hawaiian monarch to convert to Christianity', 'Founding the city of Honolulu', 'Signing Hawaii''s annexation treaty with the U.S.']::text[], true, 3, null),
  ('0e2b6abc-5ca1-542e-99af-93af79a30ab3', 'know', 'What famous song did Queen Liliuokalani compose?', 'Aloha ʻOe', ARRAY['Hawaii Ponoʻī', 'Ke Aloha O Ka Haku', 'Waikiki']::text[], true, 4, null),
  ('0e2b6abc-5ca1-542e-99af-93af79a30ab3', 'era', 'Liliuokalani''s overthrow in 1893 was carried out by whom?', 'A group of American and European businessmen (the Committee of Safety)', ARRAY['The Spanish Navy', 'The British Royal Navy', 'A rival Hawaiian royal family']::text[], true, 5, null),
  ('0e2b6abc-5ca1-542e-99af-93af79a30ab3', 'legacy', 'What did Liliuokalani do during her imprisonment at ''Iolani Palace?', 'Wrote music and an autobiography, "Hawaii''s Story by Hawaii''s Queen"', ARRAY['Negotiated Hawaii''s independence treaty', 'Led an armed escape', 'Formally renounced her Hawaiian citizenship']::text[], true, 6, null),
  ('df9e841c-7ae6-56b9-985f-31a91158683b', 'know', 'What famous haka is Te Rauparaha credited with composing?', 'Ka Mate', ARRAY['Ka Panapana', 'Tika Tonu', 'Kapa o Pango']::text[], true, 3, null),
  ('df9e841c-7ae6-56b9-985f-31a91158683b', 'nickname', 'What nickname did Europeans give Te Rauparaha for his military prowess?', 'The Napoleon of the South', ARRAY['The Lion of the Pacific', 'The Iron Chief', 'The Conqueror of Cook Strait']::text[], true, 4, null),
  ('df9e841c-7ae6-56b9-985f-31a91158683b', 'era', 'Te Rauparaha rose to prominence during what period of intertribal Maori conflict, fueled by newly acquired European weapons?', 'The Musket Wars', ARRAY['The New Zealand Wars', 'The Waikato Wars', 'The Taranaki Wars']::text[], true, 5, null),
  ('df9e841c-7ae6-56b9-985f-31a91158683b', 'legacy', 'What lasting legacy did Te Rauparaha leave through his leadership of Ngāti Toa?', 'Establishing Ngāti Toa as a dominant power around Cook Strait', ARRAY['Uniting all Maori tribes into a single kingdom', 'Signing the Treaty of Waitangi on behalf of all iwi', 'Founding the city of Wellington']::text[], true, 6, null),
  ('536a3dc1-484e-588c-8d91-4d66972f4ac0', 'know', 'What major legal document did George Tupou I promulgate in 1875?', 'The Constitution of Tonga', ARRAY['The Treaty of Waitangi', 'The Fijian Deed of Cession', 'The Tongan Bill of Rights']::text[], true, 3, null),
  ('536a3dc1-484e-588c-8d91-4d66972f4ac0', 'know', 'What two traditional Tongan titles did George Tupou I combine in 1852 to consolidate his authority?', 'The Tu''i Tonga and Tu''i Kanokupolu titles', ARRAY['The Tu''i Ha''apai and Tu''i Vava''u titles', 'The Tu''i Fiji and Tu''i Samoa titles', 'The Malietoa and Mata''afa titles']::text[], true, 4, null),
  ('536a3dc1-484e-588c-8d91-4d66972f4ac0', 'era', 'George Tupou I''s unification and reforms of Tonga occurred amid increasing what in the Pacific?', 'European missionary and colonial influence', ARRAY['Japanese naval expansion', 'Russian exploration', 'American whaling bans']::text[], true, 5, null),
  ('536a3dc1-484e-588c-8d91-4d66972f4ac0', 'legacy', 'What is George Tupou I remembered as in Tongan history?', 'The founder of modern, unified Tonga and its constitutional monarchy', ARRAY['The last independent king before Tonga became a British colony', 'A ceremonial king with no real political power', 'The king who lost Tonga''s independence to Germany']::text[], true, 6, null);
